+    fn restart_projection(&self, id: &str, generation: u64, reason: &str) {
+        if !self.projection_generation_is_current(id, generation) {
+            return;
+        }
+        let attempts = self
+            .projection_restart_count
+            .get_untracked()
+            .saturating_add(1);
+        log::warn!("restarting session projection for {id}: {reason} (attempt {attempts})");
+        let next = generation.wrapping_add(1);
+        self.sse_generation.set(next);
+        self.planner_stream_sources
+            .borrow_mut()
+            .reset(id.to_string(), next);
+        batch(|| {
+            // Folded fields belong to the retired cursor and must not survive a
+            // reset while the replacement snapshot is unavailable.
+            self.streaming.set(false);
+            self.active_turn_id.set(None);
+            self.browser_active.set(false);
+            self.browser_last_action.set(None);
+            self.pending_permissions.set(Vec::new());
+            self.active_decision_token.set(None);
+        });
+        if attempts > 4 {
+            self.status.set("session projection unavailable".into());
+            self.status_detail.set(Some((
+                "session projection unavailable".into(),
+                reason.into(),
+            )));
+            return;
+        }
+        self.projection_restart_count.set(attempts);
+        self.status.set("resyncing session…".into());
+        self.spawn_projection_sync(id.to_string(), next);
+    }
