+            .last_turn_finished
+            .as_ref()
+            .and_then(|event| match event {
+                AgentEvent::TurnFinished {
+                    input_tokens,
+                    output_tokens,
+                    cache_read_tokens,
+                    tokens_per_second,
+                    ..
+                } => Some(TokenStats {
