/// Origin rail for a session-projection frame.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SessionProjectionSource {
    Agent,
    Control,
    Checkpoint,
}

/// One ordered, session-scoped projection frame. Agent/control events retain
/// their existing wire shape. Checkpoint events decode as
/// [`SessionProjectionCheckpoint`]. Snapshot `pending_events` are reduced in
/// cursor order only for transcript/tool/component/checkpoint content; folded
/// state is installed separately and must not also be reduced from these frames.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SessionProjectionFrame {
    pub cursor: String,
    pub source: SessionProjectionSource,
    pub event: Value,
}

/// Authoritative folded replacements not fully represented by provider history.
/// After hydrating session content and reducing `pending_events`, clients install
/// every field here as the final active/terminal/reroute/permission/browser
/// value. Components are intentionally absent: reconstruct their canonical
/// registry by scanning checkpoint/session tool context in order and applying a
/// `component_render`/`component_unmount` call only after a later successful
/// (`is_error == false`) result with the same `tool_call_id`. Failed, missing,
/// or result-before-call pairs have no component effect. Then reduce component
/// frames after the checkpoint. Folded fields are not reducer inputs.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
pub struct SessionProjectionState {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub active_turn: Option<Value>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_turn_finished: Option<Value>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub model_rerouted: Option<Value>,
    #[serde(default)]
    pub pending_permissions: Vec<Value>,
    #[serde(default)]
    pub browser_active: bool,
}

/// Typed durable transcript/tool replacement carried by checkpoint frames.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", deny_unknown_fields)]
pub enum SessionProjectionCheckpoint {
    /// Inline normalized replacement. Clients replace transcript/tool context
    /// and reconstruct components by scanning tool context in order: retain a
    /// component render/unmount call until a later result with the same call id,
    /// apply it only when that result has `is_error == false`, and discard it on
    /// failed or missing result. Raw provider messages and image/base64 bytes are
    /// deliberately absent.
    #[serde(rename = "projection_checkpoint")]
    Inline {
        persistence_revision: u64,
        transcript: Vec<SessionTranscriptEntry>,
        tool_context: Vec<SessionToolContext>,
    },
    /// The exact replacement exceeded the journal's inline bound. A live-tail
    /// client must stop and refetch the canonical session snapshot. On the fresh
    /// GET that follows, canonical `session` content already satisfies this
    /// marker, so it is not recursively refetched.
    #[serde(rename = "projection_checkpoint_refetch")]
    Refetch { persistence_revision: u64 },
}

impl SessionProjectionCheckpoint {
    pub fn persistence_revision(&self) -> u64 {
        match self {
            Self::Inline {
                persistence_revision,
                ..
            }
            | Self::Refetch {
                persistence_revision,
            } => *persistence_revision,
        }
    }

    pub fn requires_refetch(&self) -> bool {
        matches!(self, Self::Refetch { .. })
    }
}

/// Atomic session snapshot watermark and retained frames after its durable base.
///
/// Initial reduction precedence is normative:
/// 1. hydrate canonical `session` from the enclosing `SessionResponse`;
/// 2. treat this top-level aligned checkpoint as the durable base. Inline
///    replaces normalized transcript/tool content; reconstruct components by
///    pairing calls with later successful same-`tool_call_id` results in order.
///    Failed, missing, or result-before-call pairs do nothing. Refetch is already
///    satisfied by this same fresh GET;
/// 3. reduce `pending_events` exactly once in cursor order for transcript/tool/
///    component/checkpoint content. Inline checkpoint replaces those canonical
///    registries; refetch aborts attach and starts a new GET;
/// 4. install every field in `state` as an authoritative replacement, never as
///    additional reducer events. Components are not folded state;
/// 5. open the exclusive tail after `cursor`; tail frames reduce normally and a
///    tail refetch checkpoint restarts this algorithm.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SessionProjection {
    pub version: u32,
    pub cursor: String,
    pub checkpoint_revision: u64,
    /// Latest visible durable replacement. Live clients receive the same typed
    /// payload on the checkpoint source.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub checkpoint: Option<SessionProjectionCheckpoint>,
    /// Identified bounded replay lease required by the projection tail.
    pub lease_id: String,
    pub lease_expires_ms: i64,
    #[serde(default)]
    pub pending_events: Vec<SessionProjectionFrame>,
    #[serde(default)]
    pub state: SessionProjectionState,
}

/// Response payload for `GET /v1/sessions/{id}`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SessionResponse {
    pub ok: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub session: Option<SessionDetail>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub projection: Option<SessionProjection>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
}


