  3465	                return;
  3466	            }
  3467	            let url = self.url.get_untracked();
  3468	            let get_url = format!("{}/v1/sessions/{id}", url.trim_end_matches('/'));
  3469	            let fetched = Request::get(&get_url).send().await;
  3470	            if !self.projection_generation_is_current(&id, generation) {
  3471	                return;
  3472	            }
