4075	                self.permission_stream_ready.get_untracked().as_ref(),
4076	            ) && planner_sources_open(&self.planner_stream_sources.borrow(), id, generation)
4077	            {
4078	                self.reconcile_pending_permissions(id).await?;
4079	                if self.session_id.get_untracked().as_deref() == Some(id)
